def transform(grid):
    from collections import Counter
    colors = Counter()
    for row in grid:
        for val in row:
            colors[val] += 1
    background = max(colors, key=colors.get)

    def get_bbox(color):
        positions = [(r, c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] == color]
        if not positions:
            return [], 0, 0, 0
        min_r, max_r = min(p[0] for p in positions), max(p[0] for p in positions)
        min_c, max_c = min(p[1] for p in positions), max(p[1] for p in positions)
        return positions, min_r, max_r, min_c, max_c

    # Find color with most compact (square/rectangular) shape
    best_color = None
    best_compact = -1

    for color in colors:
        if color != background:
            pos, m_r, M_r, m_c, M_c = get_bbox(color)
            if len(pos) == 0:
                continue
            aspect = (M_r - m_r + 1) * (M_c - m_c + 1)
            perimeter = len(pos)
            chi = perimeter / aspect if aspect > 0 else 0
            if chi > best_compact:
                best_compact = chi
                best_color = color

    if best_color is None:
        best_color = max(colors.keys())

    result = [[best_color, best_color], [best_color, best_color], [best_color, background]]
    return result
